    /// - Remark: Generated from `#/paths//v1/transactions/{transactionId}/deadline/put(set_session_deadline)`.
    func setSessionDeadline(_ input: Operations.SetSessionDeadline.Input) async throws -> Operations.SetSessionDeadline.Output
    /// Removes a session's charge-by deadline.
