/// Convenience overloads for operation inputs.
extension APIProtocol {
    /// Approve an assistant connection
    ///
    /// Called by the console's consent page with the customer's own session.
    /// Refuses an assistant credential and an API key.
    ///
    /// - Remark: HTTP `POST /v1/assistant/authorizations`.
    /// - Remark: Generated from `#/paths//v1/assistant/authorizations/post(approve_assistant)`.
    public func approveAssistant(
        headers: Operations.ApproveAssistant.Input.Headers = .init(),
        body: Operations.ApproveAssistant.Input.Body
    ) async throws -> Operations.ApproveAssistant.Output {
        try await approveAssistant(Operations.ApproveAssistant.Input(
            headers: headers,
            body: body
        ))
    }
    /// Decline an assistant connection
    ///
    /// The redirect carries `error=access_denied`, `state` when sent, and `iss`.
    ///
    /// - Remark: HTTP `POST /v1/assistant/authorizations/decline`.
    /// - Remark: Generated from `#/paths//v1/assistant/authorizations/decline/post(decline_assistant)`.
    public func declineAssistant(
        headers: Operations.DeclineAssistant.Input.Headers = .init(),
        body: Operations.DeclineAssistant.Input.Body
    ) async throws -> Operations.DeclineAssistant.Output {
        try await declineAssistant(Operations.DeclineAssistant.Input(
            headers: headers,
            body: body
        ))
    }
    /// Look up the assistant asking to connect
    ///
    /// Called by the console's consent page with the customer's own session.
    /// Refuses an assistant credential and an API key.
    ///
    /// - Remark: HTTP `GET /v1/assistant/clients/{clientId}`.
    /// - Remark: Generated from `#/paths//v1/assistant/clients/{clientId}/get(get_assistant_client)`.
    public func getAssistantClient(
        path: Operations.GetAssistantClient.Input.Path,
        query: Operations.GetAssistantClient.Input.Query = .init(),
        headers: Operations.GetAssistantClient.Input.Headers = .init()
    ) async throws -> Operations.GetAssistantClient.Output {
        try await getAssistantClient(Operations.GetAssistantClient.Input(
            path: path,
            query: query,
            headers: headers
        ))
    }
    /// Start an assistant conversation
    ///
    /// For the signed-in member, in one project and the request's mode. Starting
    /// one closes the member's other open conversations in that organization. A
    /// person's own session only: an API key or an assistant credential is
    /// refused.
    ///
    /// - Remark: HTTP `POST /v1/assistant/conversations`.
    /// - Remark: Generated from `#/paths//v1/assistant/conversations/post(start_assistant_conversation)`.
    public func startAssistantConversation(
        headers: Operations.StartAssistantConversation.Input.Headers = .init(),
        body: Operations.StartAssistantConversation.Input.Body
    ) async throws -> Operations.StartAssistantConversation.Output {
        try await startAssistantConversation(Operations.StartAssistantConversation.Input(
            headers: headers,
            body: body
        ))
    }
    /// Send an assistant message
    ///
    /// The body is `text/event-stream`. Each frame's `event:` is its `type`
    /// (`delta`, `choice`, `proposal`, `limit`, `done`) and its `data:` is one
    /// JSON [`AssistantStreamEvent`]. The stream always ends with `done`; a
    /// provider refusal or outage arrives as `delta` text then `done` with
    /// `unavailable`. Only the member who started the conversation may post.
    ///
    /// - Remark: HTTP `POST /v1/assistant/conversations/{conversationId}/messages`.
